17:package com.cockpitbench.climatix.vehicle.catalog
18:
19:import org.xmlpull.v1.XmlPullParser
20:
21:class VehicleSignalCatalogParser {
22:    fun parse(parser: XmlPullParser): List<VehicleSignalDefinition> {
23:        val signals = mutableListOf<VehicleSignalDefinition>()
24:        while (parser.eventType != XmlPullParser.END_DOCUMENT) {
25:            if (parser.eventType == XmlPullParser.START_TAG && parser.name == "signal") {
26:                signals += VehicleSignalDefinition(
27:                    key = parser.required("key"),
28:                    propertyId = parser.required("propertyId").removePrefix("0x").toLong(16).toInt(),
29:                    valueType = SignalValueType.valueOf(parser.required("valueType")),
30:                    access = SignalAccess.valueOf(parser.required("access")),
31:                    changeMode = SignalChangeMode.valueOf(parser.required("changeMode")),
32:                    unit = parser.required("unit"),
33:                    minimum = parser.optional("minimum")?.toDoubleOrNull(),
34:                    maximum = parser.optional("maximum")?.toDoubleOrNull(),
35:                    zones = parser.required("zones").split(',').filter(String::isNotBlank).toSet(),
36:                    permission = parser.required("permission"),
37:                    staleAfterMs = parser.required("staleAfterMs").toLong(),
38:                )
39:            }
40:            parser.next()
41:        }
42:        return signals
43:    }
44:
45:    private fun XmlPullParser.required(name: String): String =
46:        getAttributeValue(null, name) ?: error("Missing $name at line $lineNumber")
47:    private fun XmlPullParser.optional(name: String): String? = getAttributeValue(null, name)
48:}
