17:package com.cockpitbench.climatix.vehicle.catalog
18:
19:enum class SignalValueType { BOOLEAN, INTEGER, FLOAT, STRING }
20:enum class SignalAccess { READ, WRITE, READ_WRITE }
21:enum class SignalChangeMode { STATIC, ON_CHANGE, CONTINUOUS }
22:
23:data class VehicleSignalDefinition(
24:    val key: String,
25:    val propertyId: Int,
26:    val valueType: SignalValueType,
27:    val access: SignalAccess,
28:    val changeMode: SignalChangeMode,
29:    val unit: String,
30:    val minimum: Double?,
31:    val maximum: Double?,
32:    val zones: Set<String>,
33:    val permission: String,
34:    val staleAfterMs: Long,
35:) {
36:    init {
37:        require(key.matches(Regex("[a-z][a-z0-9_]+")))
38:        require(propertyId > 0)
39:        require(minimum == null || maximum == null || minimum <= maximum)
40:        require(permission.isNotBlank())
41:        require(staleAfterMs >= 0)
42:    }
43:}
44:
45:class VehicleSignalCatalog(definitions: Collection<VehicleSignalDefinition>) {
46:    private val byKey = definitions.associateBy(VehicleSignalDefinition::key)
47:    private val byId = definitions.associateBy(VehicleSignalDefinition::propertyId)
48:
49:    init {
50:        require(byKey.size == definitions.size) { "Vehicle signal keys must be unique" }
51:        require(byId.size == definitions.size) { "Vehicle property IDs must be unique" }
52:    }
53:
54:    fun requireKey(key: String): VehicleSignalDefinition = byKey[key] ?: error("Missing vehicle signal: $key")
55:    fun find(propertyId: Int): VehicleSignalDefinition? = byId[propertyId]
56:    fun writable(): List<VehicleSignalDefinition> = byKey.values.filter { it.access != SignalAccess.READ }.sortedBy { it.key }
57:    fun staleThreshold(propertyId: Int): Long? = byId[propertyId]?.staleAfterMs
58:    fun size(): Int = byKey.size
59:}
