18:
19:import android.os.IBinder
20:import android.os.RemoteException
21:import com.cockpitbench.climatix.domain.*
22:import java.util.concurrent.atomic.AtomicLong
23:import kotlinx.coroutines.flow.Flow
24:import kotlinx.coroutines.flow.MutableStateFlow
25:import kotlinx.coroutines.flow.onStart
26:import kotlinx.coroutines.flow.update
27:
28:class BinderClimateGateway(
29:    private val locator: ClimateServiceLocator,
30:    private val mapper: ClimateSignalMapper,
31:) : ClimateRepository {
32:    private val lock = Any()
33:    private val requestIds = AtomicLong()
34:    private val state = MutableStateFlow(ClimateState.initial())
35:    @Volatile private var service: IClimateControl? = null
36:    private var activeBinder: IBinder? = null
37:    private var deathRecipient: IBinder.DeathRecipient? = null
38:
39:    private val listener = object : IClimateListener.Stub() {
40:        override fun onSignalChanged(signal: ClimateSignal) {
41:            state.update { mapper.apply(it, signal).copy(connected = true) }
42:        }
43:
44:        override fun onConnectionChanged(connected: Boolean, revision: Long) {
45:            state.update { it.copy(connected = connected, revision = maxOf(it.revision, revision)) }
46:        }
47:    }
48:
49:    override fun observe(): Flow<ClimateState> = state.onStart {
50:        ensureConnected().onFailure { state.update { current -> current.copy(connected = false) } }
51:    }
52:
53:    override suspend fun execute(command: ClimateCommand): Result<Unit> = runCatching {
54:        val mapped = mapper.command(command)
55:        val request = ClimateWriteRequest(requestIds.incrementAndGet(), mapped.first, mapped.second, mapped.third, "climatix-app")
56:        val first = ensureConnected().getOrThrow()
57:        val result = try {
58:            first.write(request)
59:        } catch (remote: RemoteException) {
60:            invalidate(activeBinder)
61:            ensureConnected().getOrThrow().write(request)
62:        }
63:        check(result.requestId == request.requestId) { "Mismatched climate response request ID" }
64:        check(result.isAccepted) { "Climate write rejected (${result.errorCode}): ${result.message}" }
65:    }
66:
67:    override suspend fun reconnect(): Result<Unit> = runCatching {
68:        invalidate(activeBinder)
69:        ensureConnected().getOrThrow()
70:    }
71:
72:    private fun ensureConnected(): Result<IClimateControl> {
73:        service?.let { return Result.success(it) }
74:        return synchronized(lock) {
75:            service?.let { return@synchronized Result.success(it) }
76:            runCatching {
77:                val binder = locator.find() ?: error("Climate Binder service is unavailable")
78:                val api = IClimateControl.Stub.asInterface(binder)
79:                val death = IBinder.DeathRecipient { invalidate(binder) }
80:                binder.linkToDeath(death, 0)
81:                try {
82:                    api.registerListener(listener)
83:                    api.capabilities
84:                } catch (failure: Throwable) {
85:                    runCatching { binder.unlinkToDeath(death, 0) }
86:                    throw failure
87:                }
88:                activeBinder = binder
89:                deathRecipient = death
90:                service = api
91:                state.update { it.copy(connected = true) }
92:                api
93:            }
94:        }
95:    }
96:
97:    private fun invalidate(expected: IBinder?) {
98:        val detached = synchronized(lock) {
99:            if (expected == null || activeBinder !== expected) return
100:            val api = service
101:            val binder = activeBinder
102:            val death = deathRecipient
103:            service = null
104:            activeBinder = null
105:            deathRecipient = null
106:            Triple(api, binder, death)
107:        }
108:        runCatching { detached.first?.unregisterListener(listener) }
109:        val binder = detached.second
110:        val death = detached.third
111:        if (binder != null && death != null) {
112:            runCatching { binder.unlinkToDeath(death, 0) }
113:        }
114:        state.update { it.copy(connected = false, revision = it.revision + 1) }
115:    }
116:
117:    override fun close() {
118:        invalidate(activeBinder)
119:    }
120:}

