16:package com.android.car.hvac;
17:
18:import android.car.hardware.CarPropertyConfig;
19:import android.car.hardware.hvac.CarHvacManager;
20:import android.content.Context;
21:
22:import java.util.List;
23:
24:public class HvacPolicy {
25:    private float mMaxHardwareTemp;
26:    private float mMinHardwareTemp;
27:    private int mMaxHardwareFanSpeed;
28:
29:    private final boolean mHardwareUsesCelsius;
30:    private final boolean mUserUsesCelsius;
31:
32:    public HvacPolicy(Context context, List<CarPropertyConfig> properties) {
33:        //TODO handle max / min per each zone
34:        for (CarPropertyConfig config : properties) {
35:            switch (config.getPropertyId()) {
36:                case CarHvacManager.ID_ZONED_FAN_SPEED_SETPOINT: {
37:                    // Since we are using one max value to represent all zones, it should find
38:                    // the minimum max value for fan speed for all zones.
39:                    mMaxHardwareFanSpeed = Integer.MAX_VALUE;
40:                    for(int areaId : config.getAreaIds()) {
41:                        Integer newValue = (Integer) config.getMaxValue(areaId);
42:                        if (newValue != null && newValue < mMaxHardwareFanSpeed) {
43:                            mMaxHardwareFanSpeed = newValue;
44:                        }
45:                    }
46:                } break;
47:
48:                case CarHvacManager.ID_ZONED_TEMP_SETPOINT: {
49:                    // Since we are using one max value and one min value to represent all zones,
50:                    // it should find the minimum max value and maximum min value for temp for all
51:                    // zones.
52:                    mMaxHardwareTemp = Float.MAX_VALUE;
53:                    mMinHardwareTemp = -Float.MAX_VALUE;
54:                    for(int areaId : config.getAreaIds()) {
55:                        Float newValue = (Float) config.getMaxValue(areaId);
56:                        if (newValue != null && newValue < mMaxHardwareTemp) {
57:                            mMaxHardwareTemp = newValue;
58:                        }
59:                        newValue = (Float) config.getMinValue(areaId);
60:                        if (newValue != null && newValue > mMinHardwareTemp) {
61:                            mMinHardwareTemp = newValue;
62:                        }
63:                    }
64:                } break;
65:            }
66:        }
67:
68:        mHardwareUsesCelsius = context.getResources().getBoolean(R.bool.config_hardwareUsesCelsius);
69:        mUserUsesCelsius = context.getResources().getBoolean(R.bool.config_userUsesCelsius);
70:    }
71:
72:    public float userToHardwareTemp(int temp) {
73:        if (!mUserUsesCelsius && mHardwareUsesCelsius) {
74:            return fahrenheitToCelsius(temp);
75:        }
76:
77:        if (mUserUsesCelsius && !mHardwareUsesCelsius) {
78:            return celsiusToFahrenheit(temp);
79:        }
80:
81:        return temp;
82:    }
83:
84:    public int hardwareToUserTemp(float temp) {
85:        if (mHardwareUsesCelsius && !mUserUsesCelsius) {
86:            return (int) celsiusToFahrenheit(temp);
87:        }
88:
89:        if (!mHardwareUsesCelsius && mUserUsesCelsius) {
90:            return (int) fahrenheitToCelsius(temp);
91:        }
92:
93:        return (int) temp;
94:    }
95:
96:    private float celsiusToFahrenheit(float c) {
97:        return c * 9 / 5 + 32;
98:    }
99:
100:    private float fahrenheitToCelsius(float f) {
101:        return (f - 32) * 5 / 9;
102:    }
103:
104:    public int userToHardwareFanSpeed(int speed) {
105:        return getMaxHardwareFanSpeed() * speed / 100;
106:    }
107:
108:    public int hardwareToUserFanSpeed(int speed) {
109:        return speed * 100 / getMaxHardwareFanSpeed();
110:    }
111:
112:    public int getMaxHardwareFanSpeed() {
113:        return mMaxHardwareFanSpeed;
114:    }
115:
116:    public float getMaxHardwareTemp() {
117:        return mMaxHardwareTemp;
118:    }
119:
120:    public float getMinHardwareTemp() {
121:        return mMinHardwareTemp;
122:    }
123:}
