552:    /**
553:     * Handles the necessary setup/clean up before and after a state transition.
554:     */
555:    private class HvacPanelStateTransition {
556:        private @HvacPanelState int mEndState;
557:        private @HvacPanelState int mStartState;
558:
559:        public HvacPanelStateTransition(@HvacPanelState int startState,
560:                @HvacPanelState int endState) {
561:            mStartState = startState;
562:            mEndState = endState;
563:        }
564:
565:        public void onTransitionStart() {
566:            mInAnimation = true;
567:            if (mEndState == STATE_FULL_EXPANDED) {
568:                mPassengerTemperatureBarExpanded.setVisibility(View.VISIBLE);
569:                mDriverTemperatureBarExpanded.setVisibility(View.VISIBLE);
570:                if (mShowCollapsed) {
571:                    mDriverTemperatureBarCollapsed.setVisibility(View.INVISIBLE);
572:                    mPassengerTemperatureBarCollapsed.setVisibility(View.INVISIBLE);
573:                }
574:                mContainer.setAlpha(1);
575:                mContainer.setVisibility(View.VISIBLE);
576:            }
577:        }
578:
579:        public void onTransitionComplete() {
580:            if (mEndState == STATE_COLLAPSED) {
581:                if (mShowCollapsed) {
582:                    mDriverTemperatureBarCollapsed.setVisibility(View.VISIBLE);
583:                    mPassengerTemperatureBarCollapsed.setVisibility(View.VISIBLE);
584:                }
585:                handler.postAtFrontOfQueue(() -> {
586:                    mDriverTemperatureBarExpanded.setVisibility(View.INVISIBLE);
587:                    mPassengerTemperatureBarExpanded.setVisibility(View.INVISIBLE);
588:                });
589:            }
590:            if (mStartState == STATE_FULL_EXPANDED) {
591:                mContainer.setVisibility(View.INVISIBLE);
592:            }
593:
594:            // set new states
595:            mCurrentState = mEndState;
596:            mInAnimation = false;
597:        }
598:    }
599:}
